//! THE HAEST MODEL CATALOG: the models a picker offers, and what each one
//! accepts. Several readers need the same answer: a picker marks each model's
//! modalities, haest strips an attachment the current model cannot take (an image
//! sent to a text-only model is a 404 on OpenRouter, not a degraded answer),
//! compaction and a context meter size against the context window, and haest
//! must not ask a mandatory-reasoning model to stop thinking (a 400 every turn).
//!
//! The bundled rows (`catalog/models.json`) are generated by
//! `scripts/gen-catalog.ts` from the TypeScript catalog and loaded at compile
//! time. A spec NOT in the catalog has unknown modalities and haest passes
//! attachments through untouched; the provider's own error is the answer then.
//! A host may bring its own rows with [`Catalog::new`].

use std::{
    collections::{HashMap, HashSet},
    sync::LazyLock,
};

use haest_core::catalog::{InputModality, ModelGroup, ModelInfo, ModelPricing, Reasoning};
use serde::Deserialize;

const BUNDLED: &str = include_str!("../catalog/models.json");

static BUILTIN: LazyLock<Catalog> = LazyLock::new(|| {
    Catalog::from_json(BUNDLED).expect("the bundled catalog/models.json is valid")
});

/// The models haest knows, grouped for a picker, and what each accepts: input
/// modalities, context window, reasoning levels and price.
///
/// [`Catalog::builtin`] is haest's own; a host with its own models builds one
/// with [`Catalog::new`] or [`Catalog::from_json`]. Every lookup is by spec
/// (`openrouter:anthropic/claude-sonnet-5.5`) and answers None for a model the
/// catalog does not know: unknown, never assumed text-only.
///
/// # Examples
///
/// ```
/// use haest_core::{catalog::InputModality, error::BoxError};
/// use haest_providers::Catalog;
///
/// # fn main() -> Result<(), BoxError> {
/// let catalog = Catalog::from_json(r#"{"defaultModel": "local:m", "groups": [{"label": "Local",
///     "models": [{"spec": "local:m", "label": "M", "input": ["text", "image"], "contextWindow": 128000}]}]}"#)?;
/// let row = catalog.model(catalog.default_model()).ok_or("no row for the default")?;
/// assert_eq!(row.context_window, 128_000);
/// let takes_images = catalog.input_modalities("local:m").map(|m| m.contains(&InputModality::Image));
/// assert_eq!(takes_images, Some(true));
/// assert_eq!(catalog.model("local:other"), None);
///
/// // haest's own catalog always knows its default model.
/// let builtin = Catalog::builtin();
/// assert!(builtin.model(builtin.default_model()).is_some());
/// # Ok(())
/// # }
/// ```
#[derive(Debug, Clone)]
pub struct Catalog {
    default_model: String,
    groups: Vec<ModelGroup>,
    /// spec -> (group, row).
    by_spec: HashMap<String, (usize, usize)>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct CatalogFile {
    default_model: String,
    groups: Vec<ModelGroup>,
}

impl Catalog {
    /// The catalog bundled with haest, parsed on first use.
    pub fn builtin() -> &'static Catalog {
        &BUILTIN
    }

    /// A catalog of the host's own rows. `default_model` is not checked
    /// against them; a spec listed twice answers with its last row.
    pub fn new(default_model: impl Into<String>, groups: Vec<ModelGroup>) -> Self {
        let by_spec = groups
            .iter()
            .enumerate()
            .flat_map(|(g, group)| {
                group
                    .models
                    .iter()
                    .enumerate()
                    .map(move |(m, row)| (row.spec.clone(), (g, m)))
            })
            .collect();
        Self {
            default_model: default_model.into(),
            groups,
            by_spec,
        }
    }

    /// `{"defaultModel": "...", "groups": [...]}`, the shape `catalog/models.json` has.
    ///
    /// # Errors
    ///
    /// The parse error when `json` is not that shape (rows as haest-core's
    /// [`ModelInfo`], camelCase keys).
    pub fn from_json(json: &str) -> Result<Self, serde_json::Error> {
        let file: CatalogFile = serde_json::from_str(json)?;
        Ok(Self::new(file.default_model, file.groups))
    }

    /// The spec haest runs when nothing else is configured.
    pub fn default_model(&self) -> &str {
        &self.default_model
    }

    /// The groups, in the order a picker shows them.
    pub fn groups(&self) -> &[ModelGroup] {
        &self.groups
    }

    /// Every row, group by group.
    pub fn models(&self) -> impl Iterator<Item = &ModelInfo> {
        self.groups.iter().flat_map(|g| g.models.iter())
    }

    /// The row for `spec`, or None when the catalog does not know the model.
    pub fn model(&self, spec: &str) -> Option<&ModelInfo> {
        let (g, m) = *self.by_spec.get(spec)?;
        Some(&self.groups[g].models[m])
    }

    /// What `spec` accepts, or None when the catalog does not know the model.
    pub fn input_modalities(&self, spec: &str) -> Option<HashSet<InputModality>> {
        self.model(spec).map(|m| m.input.iter().copied().collect())
    }

    /// `spec`'s reasoning row, or None when unknown (not in the catalog, or a row without one).
    pub fn reasoning(&self, spec: &str) -> Option<&Reasoning> {
        self.model(spec)?.reasoning.as_ref()
    }

    /// `spec`'s price, or None when unpriced (haest then books the provider's own cost, or none).
    pub fn pricing(&self, spec: &str) -> Option<&ModelPricing> {
        self.model(spec)?.pricing.as_ref()
    }

    /// The prices of `provider`'s models, by model id (the spec without `provider:`).
    pub fn provider_pricing(&self, provider: &str) -> HashMap<String, ModelPricing> {
        let prefix = format!("{provider}:");
        self.models()
            .filter_map(|m| {
                let id = m.spec.strip_prefix(&prefix)?;
                Some((id.to_string(), m.pricing.clone()?))
            })
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use haest_core::{catalog::OpenRouterEffort, provider::parse_model_spec};

    use super::*;

    #[test]
    fn the_bundled_catalog_loads_with_unique_well_formed_specs_and_a_known_default() {
        let c = Catalog::builtin();
        let specs: Vec<&str> = c.models().map(|m| m.spec.as_str()).collect();
        assert!(!specs.is_empty());
        let unique: HashSet<&str> = specs.iter().copied().collect();
        assert_eq!(unique.len(), specs.len(), "a spec is listed twice");
        for m in c.models() {
            assert!(parse_model_spec(&m.spec).is_ok(), "{}", m.spec);
            assert!(m.input.contains(&InputModality::Text), "{}", m.spec);
            assert!(m.context_window > 0, "{}", m.spec);
        }
        assert!(c.model(c.default_model()).is_some());
    }

    #[test]
    fn the_direct_paper_instruments_row_takes_images_cannot_stop_thinking_and_is_priced() {
        let c = Catalog::builtin();
        let spec = "paperinstruments:ultramarine-1-flash";
        assert!(
            c.input_modalities(spec)
                .unwrap()
                .contains(&InputModality::Image)
        );
        let r = c.reasoning(spec).unwrap();
        assert!(r.mandatory);
        assert!(r.efforts.contains(&OpenRouterEffort::Max));
        assert_eq!(c.pricing(spec).unwrap().input, 0.15);
        let priced = c.provider_pricing("paperinstruments");
        assert_eq!(priced.get("ultramarine-1-flash"), c.pricing(spec));
    }

    #[test]
    fn an_unknown_spec_is_unknown_not_text_only() {
        let c = Catalog::builtin();
        assert_eq!(c.model("openrouter:nobody/nothing"), None);
        assert_eq!(c.input_modalities("openrouter:nobody/nothing"), None);
        assert_eq!(c.reasoning("openrouter:nobody/nothing"), None);
        assert!(
            c.provider_pricing("openrouter").is_empty(),
            "OpenRouter reports its own cost"
        );
    }

    #[test]
    fn a_host_brings_its_own_rows() {
        let json = r#"{"defaultModel": "x:m", "groups": [{"label": "X", "models": [
            {"spec": "x:m", "label": "M", "input": ["text", "audio"], "contextWindow": 1000}
        ]}]}"#;
        let c = Catalog::from_json(json).unwrap();
        assert_eq!(c.default_model(), "x:m");
        assert!(
            c.input_modalities("x:m")
                .unwrap()
                .contains(&InputModality::Audio)
        );
        assert_eq!(c.reasoning("x:m"), None);
    }
}
